mapper.select:
SELECT * FROM ( SELECT ss.* FROM ( select * from ( SELECT T1.FINPROD_ID finprodId, T1.FINPROD_ABBR finprodAbbr, T1.FINPROD_MARKET_ID finprodMarketId, T1.FINPROD_NAME finprodName, T1.TRADE_MARKET tradeMarket, T1.REGIST_ORG registOrg, T1.IDATE idate, T1.VDATE vdate, T1.MDATE mdate, T1.DELISTING_DATE delistingDate, T1.ISSUE_PRICE issuePrice, NVL(T1.ISSUE_AMT,0)/100000000 issueAmt, MST_CUSTOMER_INFO.CUSTOMER_NAME issuerName, MST_CUSTOMER_INFO.CUSTOMER_ID issuer, T4.TYPE_9 type9, T4.TYPE_10 type10, T4.TYPE_11 type11, T1.COUPON_SPECIES couponSpecies, T8.CALC_TYPE rateType, NVL(T8.YIELD,0)*100 rate, T6.BENCHMARK_ID basisRate, T6.COEFFICIENT basisRateRatio, T6.SPREAD_RATE spreadRate, T6.FIRST_CONFIRM_DATE firstRateFixDate, Case when T8.BASIS = 'A/A_B_COUP' THEN 'A/A' when T8.BASIS = 'A/A_B_DAY' THEN 'A/A' else T8.BASIS END basis, Case when T8.MARKET_BASIS = 'A/A_B_COUP' THEN 'A/A' when T8.MARKET_BASIS = 'A/A_B_DAY' THEN 'A/A' else T8.MARKET_BASIS END marketBasis, T1.IS_RIGHT isRight, T1.IS_SUS isSus, T1.ISSUE_TYPE issueType, T1.CCY ccy, T2.CROSS_MARKET_CODE crossMarketCode, T2.CONCEPT_TYPE conceptType, B.EXERCISE_TYPE exerciseType, B.EXERCISE_DATE exerciseDate, T9.PAY_CYCLE payCycle, MR.RATING mGradeResult, MR.GRADE_ORG_ID mGradeOrgId, BR.RATING bGradeResult, BR.GRADE_ORG_ID bGradeOrgId FROM FIN_PRODUCT T1 LEFT JOIN MST_CUSTOMER_INFO ON MST_CUSTOMER_INFO.CUSTOMER_ID = T1.ISSUER LEFT JOIN FIN_PRODUCT_ADD T2 ON T1.FINPROD_ID = T2.FINPROD_ID LEFT JOIN MST_CUSTOMER_INFO T3 ON T3.CUSTOMER_ID = T1.ISSUER LEFT JOIN FIN_PRODUCT_TYPE T4 ON T4.FINPROD_ID = T1.FINPROD_ID LEFT JOIN FIN_CASH_INFO T5 ON T5.FINPROD_ID = T1.FINPROD_ID
AND T5.CASH_TYPE_2 = #{cashType,jdbcType=VARCHAR}
AND T5.FINPROD_TYPE = #{finprodType,jdbcType=VARCHAR}
LEFT JOIN FIN_RATE_INFO T6 ON T6.CASH_ID = T5.CASH_ID AND T6.EFF_DATE = T1.VDATE LEFT JOIN FIN_CASH_CALC_RULE T8 ON T8.FINPROD_ID = T1.FINPROD_ID AND T8.FINPROD_TYPE = #{FINPROD_TYPE_F01} AND T8.FINPROD_TYPE2 = #{FINPROD_TYPE_F01} AND T8.BRANCH = 0 AND T8.CASH_ID = T5.CASH_ID AND T8.IS_INITIAL = 'Y' LEFT JOIN MST_CUSTOMER_INFO_ADD T7 ON T7.CUSTOMER_ID = T3.CUSTOMER_ID LEFT JOIN FIN_CASH_PAY_RULE T9 ON T9.CASH_ID = T8.CASH_ID AND T8.EFF_DATE = T9.EFF_DATE LEFT JOIN (select A.FINPROD_ID,max(A.EXERCISE_DATE) EXERCISE_DATE,A.EXERCISE_TYPE from FIN_EXERCISE_PLAN A group by A.FINPROD_ID,A.EXERCISE_TYPE) B on T1.FINPROD_ID = B.FINPROD_ID LEFT JOIN (SELECT ASSET_CODE,RATING,GRADE_ORG_ID FROM ( SELECT MBCR.O_CODE AS ASSET_CODE,MBCR.GRADE_RESULT AS RATING,MBCR.GRADE_ORG_ID as GRADE_ORG_ID ,ROW_NUMBER() OVER(PARTITION BY MBCR.O_CODE ORDER BY MBCR.O_CODE,MBCR.GRADE_DATE DESC ,MBCR.GRADE_RESULT DESC) RANK FROM MST_BOND_CREDIT_RATING MBCR WHERE MBCR.O_TYPE = '01' AND MBCR.GRADE_DATE <= TO_DATE(#{platDate},'YYYY-MM-DD') ) WHERE RANK=1 ) MR on T1.ISSUER = MR.ASSET_CODE LEFT JOIN MST_CUSTOMER_INFO T10 ON T10.CUSTOMER_ID=MR.GRADE_ORG_ID LEFT JOIN (SELECT ASSET_CODE,RATING,GRADE_ORG_ID FROM ( SELECT MBCR.O_CODE AS ASSET_CODE ,MBCR.GRADE_RESULT AS RATING,MBCR.GRADE_ORG_ID as GRADE_ORG_ID, ROW_NUMBER() OVER(PARTITION BY MBCR.O_CODE ORDER BY MBCR.O_CODE,MBCR.GRADE_DATE DESC ,MBCR.GRADE_RESULT DESC) RANK FROM MST_BOND_CREDIT_RATING MBCR WHERE MBCR.O_TYPE = '02' AND MBCR.GRADE_DATE <= TO_DATE(#{platDate},'YYYY-MM-DD') ) WHERE RANK=1) BR ON T1.FINPROD_MARKET_ID = BR.ASSET_CODE LEFT JOIN MST_CUSTOMER_INFO T11 ON T11.CUSTOMER_ID=BR.GRADE_ORG_ID where T1.FINPROD_TYPE2 = #{finprodType2}) T
AND T.finprodMarketId IN
#{item}
AND T.tradeMarket IN
#{item}
AND T.registOrg IN
#{item}
AND T.ccy IN
#{item}
AND T.type9 in
#{item}
AND T.type10 in
#{item}
AND T.type11 in
#{item}
AND T.rateType in
#{item}
AND T.couponSpecies in
#{item}
AND T.idate >= TO_DATE(#{idateStart},'YYYY-MM-DD')
AND T.idate <= TO_DATE(#{idateEnd},'YYYY-MM-DD')
AND T.vdate >= TO_DATE(#{vdateStart},'YYYY-MM-DD')
AND T.vdate <= TO_DATE(#{vdateEnd},'YYYY-MM-DD')
AND T.mdate >= TO_DATE(#{mdateStart},'YYYY-MM-DD')
AND T.mdate <= TO_DATE(#{mdateEnd},'YYYY-MM-DD')
AND T.isSus = #{isSus,jdbcType=VARCHAR}
AND T.isRight = #{isRight,jdbcType=VARCHAR}
AND T.payCycle in
#{item}
AND T.issuer in
#{item}
AND T.crossMarketCode in
#{item}
AND T.exerciseType in
#{item}
AND T.exerciseDate >= TO_DATE(#{exerciseDateStart},'YYYY-MM-DD')
AND T.exerciseDate <= TO_DATE(#{exerciseDateEnd},'YYYY-MM-DD')
AND T.mGradeResult in
#{item}
AND T.bGradeResult in
#{item}
) ss left join SYS_DATADICT_LIST sdl_tp on ss.tradeMarket=sdl_tp.ITEM_CODE and sdl_tp.DICT_CODE='TRADE_PLACE' left join SYS_DATADICT_LIST sdl_ro on ss.registOrg=sdl_ro.ITEM_CODE and sdl_ro.DICT_CODE='REGIST_ORG' left join SYS_DATADICT_LIST sdl_catt on ss.type9=sdl_catt.ITEM_CODE and sdl_catt.DICT_CODE='CUSTOM_ASSET_TYPE_TWO' left join SYS_DATADICT_LIST sdl_catth on ss.type10=sdl_catth.ITEM_CODE and sdl_catth.DICT_CODE='CUSTOM_ASSET_TYPE_THREE' left join SYS_DATADICT_LIST sdl_catf on ss.type11=sdl_catf.ITEM_CODE and sdl_catf.DICT_CODE='CUSTOM_ASSET_TYPE_FOUR' left join SYS_DATADICT_LIST sdl_cs on ss.couponSpecies=sdl_cs.ITEM_CODE and sdl_cs.DICT_CODE='COUPON_SPECIES' left join SYS_DATADICT_LIST sdl_it on ss.rateType=sdl_it.ITEM_CODE and sdl_it.DICT_CODE='INT_TYPE' left join SYS_DATADICT_LIST sdl_fu on ss.payCycle=sdl_fu.ITEM_CODE and sdl_fu.DICT_CODE='FREQUENCY_UNIT' left join SYS_DATADICT_LIST sdl_ir on ss.isRight=sdl_ir.ITEM_CODE and sdl_ir.DICT_CODE='YES_OR_NO' left join SYS_DATADICT_LIST sdl_em on ss.exerciseType=sdl_em.ITEM_CODE and sdl_em.DICT_CODE='EXEC_MODE' left join SYS_DATADICT_LIST sdl_is on ss.isSus=sdl_is.ITEM_CODE and sdl_is.DICT_CODE='YES_OR_NO' left join SYS_DATADICT_LIST sdl_ccy on ss.ccy=sdl_ccy.ITEM_CODE and sdl_ccy.DICT_CODE='CCY' left join SYS_DATADICT_LIST sdl_mgrm on ss.mGradeResult=sdl_mgrm.ITEM_CODE and sdl_mgrm.DICT_CODE='MAIN_GRADE_RESULT' left join SYS_DATADICT_LIST sdl_mgrb on ss.bGradeResult=sdl_mgrb.ITEM_CODE and sdl_mgrb.DICT_CODE='MAIN_GRADE_RESULT' left join SYS_DATADICT_LIST sdl_gpm on ss.mGradeOrgId=sdl_gpm.ITEM_CODE and sdl_gpm.DICT_CODE='GRADE_PARTY' left join SYS_DATADICT_LIST sdl_gpb on ss.bGradeOrgId=sdl_gpb.ITEM_CODE and sdl_gpb.DICT_CODE='GRADE_PARTY'
)
order by ${sort} ${direction}

if.where:
( ss.finprodId || '|' || ss.finprodName || '|' || ss.finprodAbbr || '|' || ss.finprodMarketId || '|'
                || '|' || sdl_tp.ITEM_VALUE || '|' || sdl_ro.ITEM_VALUE || '|' || ss.issuerName || '|' || sdl_catt.ITEM_VALUE || '|' || sdl_catth.ITEM_VALUE
                || '|' || sdl_catf.ITEM_VALUE || '|' || sdl_cs.ITEM_VALUE || '|' || sdl_it.ITEM_VALUE
                || '|' || sdl_fu.ITEM_VALUE || '|' || sdl_ir.ITEM_VALUE || '|' || sdl_em.ITEM_VALUE || '|' || sdl_is.ITEM_VALUE || '|' || sdl_ccy.ITEM_VALUE
                || '|' || ss.basis || '|' || ss.marketBasis || '|' || sdl_ccy.ITEM_VALUE
                || '|' || ss.crossMarketCode || '|' || ss.conceptType || '|' || sdl_mgrm.ITEM_VALUE || '|' || sdl_mgrb.ITEM_VALUE
                || '|' || sdl_gpm.ITEM_VALUE || '|' || sdl_gpb.ITEM_VALUE  || '|' || to_char(ss.basisRate)
                like '%' || #{search} || '%'
                or to_char(ss.issueAmt,'FM99990.9990')=#{search}
                or to_char(ss.issuePrice,'FM99990.9990')=#{search}
                or to_char(ss.rate)=#{search}
                or to_char(ss.basisRateRatio)=#{search}
                or to_char(ss.spreadRate)=#{search}
                or to_char(ss.idate,'YYYY-MM-DD')=#{search}
                or to_char(ss.vdate,'YYYY-MM-DD')=#{search}
                or to_char(ss.mdate,'YYYY-MM-DD')=#{search}
                or to_char(ss.delistingDate,'YYYY-MM-DD')=#{search}
                or to_char(ss.firstRateFixDate,'YYYY-MM-DD')=#{search}
                or to_char(ss.exerciseDate,'YYYY-MM-DD')=#{search}
                )

mapper.select:
select T1.FINPROD_ID FINPROD_ID, T1.FINPROD_MARKET_ID finprodMarketId, T1.FINPROD_NAME FINPROD_NAME, T1.FINPROD_ABBR FINPROD_ABBR, T1.TRADE_MARKET TRADE_MARKET, T1.REGIST_ORG REGIST_ORG, T1.ISSUE_PRICE ISSUE_PRICE, T1.IDATE IDATE, T1.VDATE VDATE, T1.MDATE MDATE, T1.DELISTING_DATE delistingDate, NVl(T1.ISSUE_AMT,0) ISSUE_AMT, T1.ISSUER ISSUER, T3.TYPE_9 TYPE_9, T3.TYPE_10 TYPE_10, T3.TYPE_11 TYPE_11, T1.ISSUE_TYPE ISSUE_TYPE, T1.IS_SUS IS_SUS, T1.IS_RIGHT IS_RIGHT, T2.IS_ALLOW_OVERWRITE IS_ALLOW_OVERWRITE, T2.IS_NETPRICE IS_NETPRICE, T2.IS_NO_GUARD IS_NO_GUARD, T1.CCY CCY, T1.CAPI_INCOME_FEATURE CAPI_INCOME_FEATURE, T2.CONCEPT_TYPE CONCEPT_TYPE, T2.CROSS_MARKET_CODE CROSS_MARKET_CODE, T1.SUSTAINABLE_REMARK sustainableRemark, T5.CON_FINPROD_ID CON_FINPROD_ID, T6.FINPROD_ABBR conFinprodName, T5.CON_VDATE CON_VDATE, T5.CON_PRICE CON_PRICE, 100/T5.CON_PRICE CON_PROPORTION, T5.RESALE_PRICE RESALE_PRICE, T5.REDEEM_PRICE REDEEM_PRICE, T5.CON_VDATE CON_VDATE, T1.COUPON_SPECIES COUPON_SPECIES, T12.CALC_TYPE CALC_TYPE, T12.YIELD YIELD, T16.BENCHMARK_ID_ACCURACY BENCHMARK_ID_ACCURACY, T16.BENCHMARK_ID basicRate, T16.COEFFICIENT coefficient, T16.SPREAD_RATE spreadRate, T16.HIGHEST_RATE highestRate, T16.LOWEST_RATE lowestRate, T16.RESET_TYPE resetType, T16.OBSERVE_BEF_DAY observeBefDay, T16.OBSERVE_BEF_UNIT observeBefUnit, T16.FIRST_CONFIRM_DATE firstConfirmDate, T12.BASIS BASIS, T12.MARKET_BASIS MARKET_BASIS, T1.REMARK REMARK, NVL(T4.CIRCULATION_DATE,T7.LISTING_DATE) listingDate, T10.CASH_ID interestCashId, T11.CASH_ID principalCashId, T13.PAY_CYCLE payCycle, T13.PAY_TDAY_RULE payTdayRule, T13.CALC_RULE calcRule, T13.FIRST_PAY_DATE firstPayDate, T2.IS_SEC_BOND isSecBond, T2.GUA_TYPE guaType, T2.ORIGINAL_OWNER originalOwner, T1.SPONSOR sponsor FROM FIN_PRODUCT T1 LEFT JOIN FIN_PRODUCT_ADD T2 ON T2.FINPROD_ID = T1.FINPROD_ID LEFT JOIN FIN_PRODUCT_TYPE T3 ON T3.FINPROD_ID = T1.FINPROD_ID LEFT JOIN FIN_PRODUCT T4 ON T4.CIRCULATION_CODE = T1.FINPROD_ID LEFT JOIN FIN_PRODUCT_ADD T7 ON T7.FINPROD_ID = T4.FINPROD_ID LEFT JOIN FIN_PRODUCT_CONVERTIBLE T5 ON T5.FINPROD_ID = T1.FINPROD_ID LEFT JOIN FIN_PRODUCT T6 ON T5.CON_FINPROD_ID = T6.FINPROD_ID AND T6.FINPROD_TYPE2=#{FINPROD_TYPE2_F10} LEFT JOIN MST_CUSTOMER_INFO T8 ON T8.CUSTOMER_ID = T1.ISSUER LEFT JOIN MST_CUSTOMER_INFO_ADD T9 ON T9.CUSTOMER_ID = T8.CUSTOMER_ID LEFT JOIN FIN_CASH_INFO T10 ON T10.FINPROD_ID = T1.FINPROD_ID AND T10.FINPROD_TYPE = #{FIN_CASH_BUSINESS_TYPE_01} AND T10.BRANCH = 0 AND T10.CASH_TYPE_1 = #{CASH_TYPE_1_02} AND T10.CASH_TYPE_2 = #{CASH_TYPE_2_C02} LEFT JOIN FIN_CASH_INFO T11 ON T11.FINPROD_ID = T1.FINPROD_ID AND T11.FINPROD_TYPE = #{FIN_CASH_BUSINESS_TYPE_01} AND T11.BRANCH = 0 AND T11.CASH_TYPE_1 = #{CASH_TYPE_1_01} AND T11.CASH_TYPE_2 = #{CASH_TYPE_2_C01} LEFT JOIN FIN_CASH_CALC_RULE T12 ON T12.FINPROD_ID = T1.FINPROD_ID AND T12.FINPROD_TYPE = #{FINPROD_TYPE_F01} AND T12.FINPROD_TYPE2 = #{FINPROD_TYPE_F01} AND T12.BRANCH = 0 AND T12.CASH_ID = T10.CASH_ID AND T12.IS_INITIAL = 'Y' LEFT JOIN FIN_CASH_PAY_RULE T13 ON T13.FINPROD_ID = T1.FINPROD_ID AND T13.FINPROD_TYPE = #{FINPROD_TYPE_F01} AND T13.FINPROD_TYPE2 = #{FINPROD_TYPE_F01} AND T13.BRANCH = 0 AND T13.CASH_ID = T10.CASH_ID LEFT JOIN FIN_RATE_INFO T16 ON T16.FINPROD_ID = T1.FINPROD_ID AND T16.FINPROD_TYPE = #{FINPROD_TYPE_F01} AND T16.FINPROD_TYPE2 = #{FINPROD_TYPE_F01} AND T16.BRANCH = 0 AND T16.CASH_ID = T10.CASH_ID
( T1.FINPROD_ID = #{finprodId}
OR T1.FINPROD_MARKET_ID = #{finprodId}) AND T1.FINPROD_TYPE2=#{finprodType} AND T1.TRADE_MARKET IN (#{TRADE_PLACE_01},#{TRADE_PLACE_02},#{TRADE_PLACE_03},#{TRADE_PLACE_04})

SELECT PAYHSRCSECINFO.SECID finprodMarketId, PAYHSRCSECINFO.SECFULLNAME FINPROD_NAME, PAYHSRCSECINFO.SECNAME FINPROD_ABBR, PAYHSRCSECINFO.MARKET TRADE_MARKET, PAYHSRCSECINFO.INSTITUTION REGIST_ORG, PAYHSRCSECINFO.ISSUEPRICE ISSUE_PRICE, PAYHSRCSECINFO.VDATE, PAYHSRCSECINFO.MDATE, PAYHSRCSECINFO.PUBENDDATE IDATE, PAYHSRCSECINFO.DELISTING_DATE delistingDate, PAYHSRCSECINFO.ISSUEAMT ISSUE_AMT, PAYHSRCSECINFO.ISSUERSHORT ISSUER, TYPE_CONFIG.INPUT_VALUE_2 TYPE_9, TYPE_CONFIG.INPUT_VALUE_3 TYPE_10, TYPE_CONFIG.INPUT_VALUE_4 TYPE_11, PAYHSRCSECINFO.ISSUETYPE ISSUE_TYPE, PAYHSRCSECINFO.ISSUS IS_SUS,
CASE WHEN ( PAYHSRCSECINFO.CALLOPTION = 'Y' OR PAYHSRCSECINFO.PUTOPTION = 'Y' ) THEN 'Y' ELSE 'N' END AS IS_RIGHT, 'Y' IS_ALLOW_OVERWRITE
FROM INTERF_PAYHSRCSECINFO PAYHSRCSECINFO LEFT JOIN FIN_PRODUCT_TYPE_CONFIG TYPE_CONFIG ON TYPE_CONFIG.INPUT_VALUE_1 = 'F01' AND TYPE_CONFIG.INPUT_VALUE_2 = PAYHSRCSECINFO.SECTYPE AND TYPE_CONFIG.INPUT_VALUE_3 = PAYHSRCSECINFO.SECTYPE2 WHERE SECID = #{finprodId}

SELECT FINPROD_ID id, FINPROD_ABBR||':'||FINPROD_MARKET_ID text FROM FIN_PRODUCT
FINPROD_TYPE2 = #{assestType}
AND ( FIN_PRODUCT.FINPROD_ABBR LIKE CONCAT('%', CONCAT(#{search}, '%')) OR FIN_PRODUCT.FINPROD_MARKET_ID LIKE CONCAT('%', CONCAT(#{search}, '%')))
AND FINPROD_ID = #{initValue}
AND FINPROD_ID NOT IN( SELECT O_FINPROD_ID FROM FIN_PRODUCT WHERE O_FINPROD_ID IS NOT NULL )

SELECT count(1)
FROM FIN_PRODUCT
WHERE O_FINPROD_ID = #{oFinprodId}
  and FINPROD_ID != #{finprodId}

mapper.delete:
delete from PA_TRD_FIN_PRODUCT_DEAL_TOTAL tfpft
where tfpft.TOTLE_TRADE_ID in (
select TOTLE_TRADE_ID from TRD_FIN_PRODUCT_DEAL_TOTAL
where trade_date =#{batchDate}
and BUSI_TYPE = #{busiType}
and PS in (#{PS_T07},#{PS_T08},#{PS_T09},#{PS_T39})
and finprod_id =#{finprodId}

    and FINPROD_TYPE2 = #{finProdType2}

)

delete from TRD_FIN_PRODUCT_DEAL_TOTAL tfpft
where tfpft.trade_date =#{batchDate}
and tfpft.BUSI_TYPE = #{busiType}
and tfpft.PS in (#{PS_T07},#{PS_T08},#{PS_T09},#{PS_T39})
and finprod_id =#{finprodId}

    and tfpft.FINPROD_TYPE2 = #{finProdType2}

delete from trd_product_deal tfpft
where tfpft.TOTLE_TRADE_ID in (
select TOTLE_TRADE_ID from TRD_FIN_PRODUCT_DEAL_TOTAL
where trade_date =#{batchDate}
and BUSI_TYPE = #{busiType}
and PS in (#{PS_T07},#{PS_T08},#{PS_T09},#{PS_T39})
and finprod_id =#{finprodId}

    and FINPROD_TYPE2 = #{finProdType2}

)

delete from trd_product_deal_add tfpft
where tfpft.trade_id in (
select tfpft.trade_id from trd_product_deal tfpft
where tfpft.TOTLE_TRADE_ID in (
select TOTLE_TRADE_ID from TRD_FIN_PRODUCT_DEAL_TOTAL
where trade_date =#{batchDate}
and BUSI_TYPE = #{busiType}
and PS in (#{PS_T07},#{PS_T08},#{PS_T09},#{PS_T39})
and finprod_id =#{finprodId}

    and FINPROD_TYPE2 = #{finProdType2}

)
)

delete from STL_PAY_ORDERS tfpft
where tfpft.TRADE_ID in (
select TOTLE_TRADE_ID from TRD_FIN_PRODUCT_DEAL_TOTAL
where trade_date =#{batchDate}
and BUSI_TYPE = #{busiType}
and PS in (#{PS_T07},#{PS_T08},#{PS_T09},#{PS_T39})
and finprod_id =#{finprodId}

    and FINPROD_TYPE2 = #{finProdType2}

)

mapper.select:
SELECT
cash_id,
CASH_TYPE,
PORTFOLIO_ID,
PORTFOLIO_NAME,
INVEST_YESORNO,
FINPROD_ID,
CDATE,
SUM(AMOUNT)/100 AMOUNT,
vDate,
mDate,
yield,
CALC_RULE
FROM (
SELECT
listagg(t5.CASH_TYPE, ',') within group ( order by t5.CASH_ID ) CASH_TYPE,
listagg(t5.CASH_ID, ',') within group ( order by t5.CASH_ID ) CASH_ID,
T1.PORTFOLIO_ID,
pp.PORTFOLIO_NAME,
pp.INVEST_YESORNO,
T1.FINPROD_ID,
T1.CDATE,
DECODE(T1.HODING_TYPE, '06', T1.AMOUNT*-1,'11', T1.AMOUNT*-1, T1.AMOUNT) AMOUNT,
'${vDate}' vDate,
'${mDate}' mDate,
'${yield}' yield,
/*现金流支付规则.支付频率 付息周期*/ T4.PAY_CYCLE CALC_RULE
/*检索对象 组合持仓*/ FROM PTL_SEC_POSITION_RULE T1
/*left join 标的类金融产品*/ LEFT JOIN FIN_PRODUCT T2
/*on 组合持仓.金融产品代码 = 标的类金融产品.金融产品代码*/ ON T1.FINPROD_ID = T2.FINPROD_ID
/*left join 现金流信息*/ LEFT JOIN FIN_CASH_INFO T3
/*on 标的类金融产品.金融产品代码 = 现金流信息.业务代码*/ ON T1.FINPROD_ID = T3.FINPROD_ID
/*and 现金流信息.现金流一级类型 = 数据字典缓存.现金流一级类型.利息*/ AND T3.CASH_TYPE_1 = #{CASH_TYPE_1_02}
/*and 现金流信息.现金流二级类型 = 数据字典缓存.现金流二级类型.利息*/ AND T3.CASH_TYPE_2 = #{CASH_TYPE_2_C02}
/*left join 现金流支付规则*/ LEFT JOIN FIN_CASH_PAY_RULE T4
/*on 现金流信息.现金流代码 = 现金流支付规则.现金流代码*/ ON T3.CASH_ID = T4.CASH_ID
/*and 生效日期 小于等于 传参.调整后计算结束日*/ AND T4.EFF_DATE <= #{adjustMDate}
LEFT JOIN FIN_CASH_PLAN T5 ON T1.FINPROD_ID = T5.FINPROD_ID AND T5.MDATE = #{adjustMDate}
LEFT JOIN PTL_PORTFOLIO pp on pp.PORTFOLIO_ID = T1.PORTFOLIO_ID
/*检索条件 金融产品代码 = 传参.金融产品代码*/ where T1.FINPROD_ID = #{finprodId}
/*and 持仓类型 = 数据字典缓存.持仓类型.实际*/

AND T1.HODING_TYPE = 'A_004'
/*and 组合持仓.日期 = 平台日*/ AND t1.CDATE < #{adjustMDate}
AND T1.SEC_ACCT_ID = #{secAcctId}
and T1.AMOUNT > 0
AND nvl(pp.PARENT_PORTFOLIO_ID,'null') = 'null'
AND NOT EXISTS (
SELECT 1 FROM PTL_SEC_POSITION_RULE tpsp
where tpsp.HODING_TYPE = T1.HODING_TYPE
and tpsp.PORTFOLIO_ID = T1.PORTFOLIO_ID
and tpsp.SEC_ACCT_ID = T1.SEC_ACCT_ID
and tpsp.FINPROD_ID = T1.FINPROD_ID
and tpsp.CDATE > T1.CDATE
and tpsp.CDATE < #{adjustMDate}
)
/*不存在生效的交易*/
and NOT EXISTS (SELECT 1 FROM TRD_FIN_PRODUCT_DEAL_TOTAL TPDA
LEFT JOIN TRD_DEAL_TOTAL_ADD TDTA ON TPDA.TOTLE_TRADE_ID = TDTA.TOTLE_TRADE_ID
where TDTA.MP_FINPROD_ID IS NULL
AND TPDA.TRADE_STATUS = #{TRADE_STATUS01}
AND TPDA.BUSI_TYPE = #{TRD10}
AND TPDA.IS_CANCEL = #{YESNO_N} and TO_DATE(#{mDate}, 'YYYY-MM-DD') = TPDA.MDATE
AND TPDA.FINPROD_ID = T1.FINPROD_ID
AND T1.PORTFOLIO_ID =TPDA.PORTFOLIO_ID
AND (TPDA.CHL_ID = T1.SEC_ACCT_ID OR TPDA.SEC_MANAGE_ACCT_ID = T1.SEC_ACCT_ID))
/*不存在流程中的当期或之前的交易*/
AND NOT EXISTS (SELECT 1 FROM WFL_TRD_FIN_PRODUCT_DEAL_TOTAL TPDA
LEFT JOIN WFL_TRD_DEAL_TOTAL_ADD TDTA ON TPDA.TOTLE_TRADE_ID = TDTA.TOTLE_TRADE_ID
where TDTA.MP_FINPROD_ID IS NULL
AND TPDA.TRADE_STATUS = #{TRADE_STATUS01}
AND TPDA.BUSI_TYPE = #{TRD10}
AND TPDA.IS_CANCEL = #{YESNO_N} and TO_DATE(#{mDate}, 'YYYY-MM-DD') >= TPDA.MDATE
AND TPDA.FINPROD_ID = T1.FINPROD_ID
AND T1.PORTFOLIO_ID =TPDA.PORTFOLIO_ID
AND (TPDA.CHL_ID = T1.SEC_ACCT_ID OR TPDA.SEC_MANAGE_ACCT_ID = T1.SEC_ACCT_ID))
group by
pp.PORTFOLIO_NAME,
T1.PORTFOLIO_ID,
T1.FINPROD_ID,
PP.INVEST_YESORNO,
T1.CDATE,
T1.AMOUNT,
T1.HODING_TYPE,
T4.PAY_CYCLE
)
group by cash_id,
CASH_TYPE,
PORTFOLIO_ID,
PORTFOLIO_NAME,
INVEST_YESORNO,
FINPROD_ID,
CDATE,
vDate,
mDate,
yield,
CALC_RULE
having SUM(AMOUNT) > 0

SELECT
FINPROD_MARKET_ID id,
case FINPROD_TYPE2 when #{FINPROD_TYPE_TG_ZQ}
then FINPROD_ABBR
ELSE FINPROD_NAME
end text,
case FINPROD_TYPE2 when #{FINPROD_TYPE_TG_ZQ}
then  FINPROD_ABBR
ELSE FINPROD_NAME end object,
FINPROD_MARKET_ID parentId
FROM FIN_PRODUCT

    FINPROD_TYPE2 in ('F01','F06','F10','F32')

        and (FINPROD_MARKET_ID like concat(concat('%',#{search}),'%')
        or FINPROD_ABBR like concat(concat('%',#{search}),'%')
        or FINPROD_NAME like concat(concat('%',#{search}),'%')
        )


        AND FINPROD_TYPE2 in

            #{item}



        AND P_FINPROD_ID IS NULL


        AND PROFIT_TYPE = #{profitType,jdbcType=VARCHAR}

SELECT T3.FINPROD_ID, T3.FINPROD_TYPE, T3.FINPROD_TYPE2, T3.FINPROD_MARKET_ID, T3.FINPROD_NAME, T3.FINPROD_ABBR, T3.ISSUE_AMT, T3.VDATE, T1.EFF_DATE, T1.CALC_TYPE, T1.BASE_TYPE, T1.BASE_DATE_TYPE, T1.BASIS, T1.YIELD YIELD, T1.IS_INITIAL, T1.BRANCH, T2.CASH_ID, T2.FEE_ID FROM FIN_CASH_CALC_RULE T1 INNER JOIN FIN_CASH_INFO T2 ON T2.CASH_ID = T1.CASH_ID LEFT JOIN FIN_PRODUCT T3 ON T3.FINPROD_ID = T1.FINPROD_ID AND T2.FINPROD_ID = T3.FINPROD_ID
AND T2.FINPROD_TYPE = #{finprodType,jdbcType=VARCHAR}
and T2.CASH_TYPE_2 in ('C11','C12','C13','C14')
AND T2.CASH_TYPE_1 = #{cashType1,jdbcType=VARCHAR}
AND T2.CASH_TYPE_2 = #{cashType2,jdbcType=VARCHAR}
AND T3.FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
order by T1.EFF_DATE ASC

SELECT T3.FINPROD_ID, T3.FINPROD_TYPE, T3.FINPROD_TYPE2, T3.FINPROD_MARKET_ID, T3.FINPROD_NAME, T3.FINPROD_ABBR, T3.ISSUE_AMT, T3.VDATE, T1.EFF_DATE, T1.CALC_TYPE, T1.BASE_TYPE, T1.BASE_DATE_TYPE, T1.BASIS, T1.MARKET_BASIS MARKET_BASIS, T1.YIELD*100 YIELD, T1.IS_INITIAL, T1.BRANCH, T2.CASH_ID, T2.FEE_ID FROM FIN_CASH_CALC_RULE T1 LEFT JOIN FIN_PRODUCT T3 ON T3.FINPROD_ID = T1.FINPROD_ID INNER JOIN FIN_CASH_INFO T2 ON T2.CASH_ID = T1.CASH_ID AND T2.FINPROD_ID = T3.FINPROD_ID
AND T2.FINPROD_TYPE = #{finprodType,jdbcType=VARCHAR}
AND T2.CASH_TYPE_1 = #{cashType1,jdbcType=VARCHAR}
AND T2.CASH_TYPE_2 = #{cashType2,jdbcType=VARCHAR}
AND T1.FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
order by T1.EFF_DATE ASC

SELECT
,T2.FINPROD_ID FINPROD_ID , T2.FINPROD_TYPE FINPROD_TYPE , T2.FINPROD_TYPE2 FINPROD_TYPE2 , T2.FINPROD_ABBR FINPROD_ABBR , T2.FINPROD_NAME FINPROD_NAME , T2.COUPON_SPECIES , T3.EFF_DATE EFF_DATE , T3.PAY_CYCLE_VAL PAY_CYCLE_VAL , T3.PAY_CYCLE PAY_CYCLE , T3.DAY_TYPE DAY_TYPE , T3.DAY_VALUE DAY_VALUE , T3.END_TDAY_RULE END_TDAY_RULE , T3.PAY_TDAY_RULE PAY_TDAY_RULE , T3.CALC_RULE CALC_RULE , T3.FIRST_PAY_DATE FIRST_PAY_DATE , T3.CASH_UNIT_TYPE CASH_UNIT_TYPE ,T3.REMARK REMARK ,T3.PAY_MONTH FROM FIN_CASH_INFO T1 LEFT JOIN FIN_PRODUCT T2 ON T2.FINPROD_ID = T1.FINPROD_ID LEFT JOIN FIN_CASH_PAY_RULE T3 ON T3.CASH_ID = T1.CASH_ID
AND T3.EFF_DATE = to_date ( #{vdate}, 'yyyy-mm-dd' )
AND T1.FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
AND T1.CASH_TYPE_2 = #{cashType,jdbcType=VARCHAR}
AND T1.FINPROD_TYPE = #{finprodType,jdbcType=VARCHAR}

SELECT T4.IS_PAY_INT FROM FIN_CASH_INFO T1 LEFT JOIN FIN_PRODUCT T2 ON T2.FINPROD_ID = T1.FINPROD_ID LEFT JOIN FIN_CASH_PLAN T4 on T4.CASH_ID =T1.CASH_ID where T2.MDATE=T4.MDATE
AND T1.FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
AND T1.CASH_TYPE_2 = #{cashType,jdbcType=VARCHAR}

SELECT T1.CASH_ID ,T1.EXERCISE_TYPE ,T1.VDATE ,T1.MDATE ,T1.EXERCISE_DATE
,T1.ACT_EXERCISE_DATE
,T1.EXERCISE_PRICE ,T1.EXERCISE_REMARK ,T1.FINPROD_ID ,T1.FINPROD_TYPE ,T1.FINPROD_TYPE2 ,T1.BRANCH ,CASE WHEN ( SELECT count( * ) count FROM TRD_PRODUCT_DEAL T3
T3.SETTLE_DATE = T1.ACT_EXERCISE_DATE
AND T3.TRADE_STATUS = '01' AND (T3.IS_CANCEL='N' or T3.IS_CANCEL IS NULL)
AND T3.FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
AND (T3.PS = #{psT03,jdbcType=VARCHAR} or T3.PS = #{psT39,jdbcType=VARCHAR})
) > 0 THEN #{execType02,jdbcType=VARCHAR} ELSE #{execType01,jdbcType=VARCHAR} END AS EXERCISE_STATUS
FROM FIN_EXERCISE_PLAN T1 inner JOIN FIN_CASH_INFO T2 ON T1.CASH_ID = T2.CASH_ID AND T1.FINPROD_ID=T2.FINPROD_ID
AND T2.CASH_TYPE_2 = #{cashType2,jdbcType=VARCHAR}
AND T1.FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
order by T1.EXERCISE_DATE asc

SELECT T1.COUPON_SPECIES, T3.INT_TYPE FROM FIN_PRODUCT T1 LEFT JOIN FIN_CASH_INFO T2 ON T2.FINPROD_ID = T1.FINPROD_ID
AND T2.CASH_TYPE_2 = #{cashType,jdbcType=VARCHAR}
LEFT JOIN FIN_RATE_INFO T3 ON T3.CASH_ID = T2.CASH_ID AND T3.EFF_DATE = T1.VDATE
AND T1.FINPROD_ID = #{finprodId,jdbcType=VARCHAR}

select pm.STATUS status
from SYS_DATA_PROCESS_MARK pm
inner join (
select
max(HIS_NO)	       HIS_NO,
WORKFLOW_ID
from SYS_DATA_PROCESS_MARK


        PAGE_ID = #{pageId}


group by  WORKFLOW_ID
) tempHis on  pm.HIS_NO = tempHis.HIS_NO and pm.WORKFLOW_ID = tempHis.WORKFLOW_ID


        pm.status in ('A','U','P')


        and pm.PAGE_ID = #{pageId}


        and pm.BUSINESS_DATA_PK1 = #{businessDataPk1}


        and pm.BUSINESS_DATA_PK2 = #{businessDataPk2}


        and pm.WORKFLOW_ID != #{workflowId}


order by pm.create_time desc

SELECT
OUTPUT_VALUE_1 outputValue1,
OUTPUT_VALUE_2 outputValue2
FROM FIN_PRODUCT_TYPE_CONFIG
WHERE CONFIG_TYPE = #{configType}

    AND INPUT_VALUE_1 = #{inputValue1}


    AND INPUT_VALUE_2 = #{inputValue2}


    AND INPUT_VALUE_3 = #{inputValue3}


    AND INPUT_VALUE_4 = #{inputValue4}
and ROWNUM=1
